// Motor de matching avanzado para conciliación México
const data = $input.all()[0].json;
const bankTxns = data.bank_transactions;
const accRecords = data.accounting_records;
const toleranceDays = data.tolerance_days;
const toleranceAmount = data.tolerance_amount;

const matches = [];
const unmatchedBank = [...bankTxns];
const unmatchedAccounting = [...accRecords];

// Función de matching con scoring ponderado
function calculateMatchScore(bankTxn, accRecord) {
  let score = 0;

  // Score por monto (40% del peso)
  const amountDiff = Math.abs(Math.abs(bankTxn.amount) - Math.abs(accRecord.amount));
  if (amountDiff <= toleranceAmount) {
    score += 40;
  } else if (amountDiff <= toleranceAmount * 2) {
    score += 20;
  }

  // Score por fecha (30% del peso)
  const bankDate = new Date(bankTxn.date);
  const accDate = new Date(accRecord.date);
  const daysDiff = Math.abs((bankDate - accDate) / (1000 * 60 * 60 * 24));
  if (daysDiff <= toleranceDays) {
    score += 30 - (daysDiff * 5);
  }

  // Score por descripción/concepto (20% del peso)
  const bankDesc = bankTxn.description.toLowerCase();
  const accDesc = accRecord.description.toLowerCase();

  if (bankDesc.includes('nomina') && accDesc.includes('nomina')) score += 20;
  else if (bankDesc.includes('cfe') && accDesc.includes('cfe')) score += 20;
  else if (bankDesc.includes('spei') && accRecord.type === 'income') score += 15;
  else if (bankDesc.includes('transferencia') && accRecord.type === 'income') score += 10;

  // Score por tipo de transacción (10% del peso)
  if ((bankTxn.amount > 0 && accRecord.amount > 0) || 
      (bankTxn.amount < 0 && accRecord.amount < 0)) {
    score += 10;
  }

  return score;
}

// Ejecutar matching
for (const bankTxn of bankTxns) {
  let bestMatch = null;
  let bestScore = 0;

  for (const accRecord of accRecords) {
    const score = calculateMatchScore(bankTxn, accRecord);
    if (score > bestScore && score >= 60) { // Umbral mínimo 60%
      bestScore = score;
      bestMatch = accRecord;
    }
  }

  if (bestMatch) {
    matches.push({
      match_id: `MATCH_${matches.length + 1}`,
      bank_transaction: bankTxn,
      accounting_record: bestMatch,
      confidence_score: bestScore,
      match_type: bestScore >= 85 ? 'exact' : 'fuzzy',
      matched_at: new Date().toISOString()
    });

    // Remover de listas de no coincidencias
    const bankIndex = unmatchedBank.indexOf(bankTxn);
    const accIndex = unmatchedAccounting.indexOf(bestMatch);
    if (bankIndex > -1) unmatchedBank.splice(bankIndex, 1);
    if (accIndex > -1) unmatchedAccounting.splice(accIndex, 1);
  }
}

// Calcular estadísticas
const stats = {
  total_bank_transactions: bankTxns.length,
  total_accounting_records: accRecords.length,
  matches_found: matches.length,
  match_rate: ((matches.length / Math.max(bankTxns.length, accRecords.length)) * 100).toFixed(2),
  unmatched_bank: unmatchedBank.length,
  unmatched_accounting: unmatchedAccounting.length,
  exact_matches: matches.filter(m => m.match_type === 'exact').length,
  fuzzy_matches: matches.filter(m => m.match_type === 'fuzzy').length
};

return [{
  ...data,
  matches: matches,
  unmatched_bank_transactions: unmatchedBank,
  unmatched_accounting_records: unmatchedAccounting,
  reconciliation_stats: stats,
  matching_complete: true,
  matching_time: new Date().toISOString()
}];

// Análisis de discrepancias financieras México
const data = $input.all()[0].json;
const unmatchedBank = data.unmatched_bank_transactions;
const unmatchedAcc = data.unmatched_accounting_records;

const discrepancies = [];
let totalDiscrepancyAmount = 0;

// Analizar transacciones bancarias no conciliadas
for (const bankTxn of unmatchedBank) {
  const discrepancy = {
    id: `DISC_B_${discrepancies.length + 1}`,
    type: 'unmatched_bank_transaction',
    source: 'bank',
    transaction: bankTxn,
    amount: bankTxn.amount,
    date: bankTxn.date,
    description: bankTxn.description,
    risk_level: 'medium',
    suggested_actions: [],
    mexican_context: {}
  };

  // Clasificar riesgo y sugerir acciones
  if (Math.abs(bankTxn.amount) > 50000) {
    discrepancy.risk_level = 'high';
    discrepancy.suggested_actions.push('Revisar con contador/CFO inmediatamente');
  } else if (Math.abs(bankTxn.amount) > 10000) {
    discrepancy.risk_level = 'medium';
    discrepancy.suggested_actions.push('Verificar con área contable');
  } else {
    discrepancy.risk_level = 'low';
    discrepancy.suggested_actions.push('Revisar en próxima conciliación');
  }

  // Contexto mexicano específico
  if (bankTxn.description.includes('SAT') || bankTxn.description.includes('HACIENDA')) {
    discrepancy.mexican_context.type = 'fiscal';
    discrepancy.suggested_actions.unshift('URGENTE: Revisar obligación fiscal');
    discrepancy.risk_level = 'critical';
  } else if (bankTxn.description.includes('INFONAVIT') || bankTxn.description.includes('IMSS')) {
    discrepancy.mexican_context.type = 'seguridad_social';
    discrepancy.suggested_actions.push('Verificar pagos seguridad social');
  }

  discrepancies.push(discrepancy);
  totalDiscrepancyAmount += Math.abs(bankTxn.amount);
}

// Analizar registros contables no conciliados
for (const accRecord of unmatchedAcc) {
  const discrepancy = {
    id: `DISC_A_${discrepancies.length + 1}`,
    type: 'unmatched_accounting_record',
    source: 'accounting',
    record: accRecord,
    amount: accRecord.amount,
    date: accRecord.date,
    description: accRecord.description,
    risk_level: 'medium',
    suggested_actions: [],
    mexican_context: {}
  };

  // Análisis específico para registros contables
  if (accRecord.cfdi_uuid) {
    discrepancy.mexican_context.cfdi_uuid = accRecord.cfdi_uuid;
    discrepancy.suggested_actions.push('Verificar CFDI en portal SAT');
  }

  if (accRecord.status === 'pending_payment') {
    discrepancy.suggested_actions.push('Verificar cobro pendiente');
    discrepancy.risk_level = 'high';
  }

  discrepancies.push(discrepancy);
  totalDiscrepancyAmount += Math.abs(accRecord.amount);
}

// Calcular métricas de discrepancias
const discrepancyAnalysis = {
  total_discrepancies: discrepancies.length,
  total_amount: totalDiscrepancyAmount,
  critical_count: discrepancies.filter(d => d.risk_level === 'critical').length,
  high_risk_count: discrepancies.filter(d => d.risk_level === 'high').length,
  medium_risk_count: discrepancies.filter(d => d.risk_level === 'medium').length,
  low_risk_count: discrepancies.filter(d => d.risk_level === 'low').length,
  fiscal_issues: discrepancies.filter(d => d.mexican_context.type === 'fiscal').length,
  pending_collections: discrepancies.filter(d => d.record?.status === 'pending_payment').length
};

return [{
