${analysis.critical_count > 0 ? '🚨 *' + analysis.critical_count + ' discrepancias críticas*' : '✅ Sin issues críticos'}

[Ver Reporte Completo](https://tu-portal.com/reports/${summary.reconciliation_id})`
};

// Notificación webhook para dashboards
const webhookNotification = {
  type: 'webhook',
  url: 'https://tu-portal.com/api/notifications/reconciliation',
  payload: {
    reconciliation_id: summary.reconciliation_id,
    status: summary.status,
    match_rate: summary.match_rate,
    risk_level: summary.risk_assessment,
    timestamp: summary.completion_time,
    requires_attention: analysis.critical_count > 0 || analysis.high_risk_count > 2
  }
};

notifications.push(emailNotification, telegramNotification, webhookNotification);

return [{
